const C = {
  ink:{r:0,g:0,b:0}, white:{r:1,g:1,b:1},
  text:{r:0.102,g:0.102,b:0.122},
  sub:{r:0.42,g:0.45,b:0.47},
  border:{r:0.859,g:0.886,b:0.898},
  tint:{r:0.906,g:0.976,b:0.992},
  surface:{r:0.969,g:0.980,b:0.984},
  fav:{r:0.96,g:0.29,b:0.26}
};
const solid = c => [{type:"SOLID",color:c}];
async function txt(chars, size, style, color, opts={}){
  const t = figma.createText();
  t.fontName = {family:"Inter",style};
  t.fontSize = size; t.characters = chars; t.fills = solid(color);
  if (opts.lh) t.lineHeight = {value:opts.lh, unit:"PIXELS"};
  if (opts.w){ t.textAutoResize="HEIGHT"; t.resize(opts.w, t.height); }
  if (opts.name) t.name = opts.name;
  return t;
}
function auto(dir, gap){
  const f = figma.createFrame();
  f.layoutMode = dir; f.itemSpacing = gap;
  f.primaryAxisSizingMode="AUTO"; f.counterAxisSizingMode="AUTO";
  f.fills=[];
  return f;
}
async function instance(id, w, h){
  const src = await figma.getNodeByIdAsync(id);
  const i = src.createInstance();
  if(w) i.resize(w, h||Math.round(i.height*(w/i.width)));
  return i;
}
function recolor(iconInst, color){
  const walk = n => {
    if(n.type==="VECTOR"){
      if(n.fills && n.fills.length) n.fills = solid(color);
      if(n.strokes && n.strokes.length) n.strokes = solid(color);
    }
    if("children" in n) n.children.forEach(walk);
  };
  walk(iconInst);
  iconInst.fills = [];
}
function setNavCurrent(headerInst, current){
  for(const item of ["Home","Recipes","Blog","Contact","About us"]){
    const t = headerInst.findOne(n=>n.name==="Nav_"+item);
    if(item===current){
      t.fontName={family:"Inter",style:"Semi Bold"};
      t.fills=solid(C.ink);
      t.textDecoration="UNDERLINE";
    } else {
      t.fills=solid(C.sub);
    }
  }
}
function section(name, gap, padV){
  const s = auto("VERTICAL", gap);
  s.name=name;
  s.paddingLeft=s.paddingRight=120;
  s.paddingTop=s.paddingBottom=(padV===undefined?80:padV);
  return s;
}
async function recipeCard(d){
  const i = (await figma.getNodeByIdAsync("1014:57")).createInstance();
  const wrap = i.children.find(n=>n.name==="Photo");
  const photo = wrap.children.find(n=>n.name==="Photo");
  const nc = await figma.getNodeByIdAsync(d.photo);
  photo.swapComponent(nc);
  i.findOne(n=>n.name==="Title").characters = d.title;
  i.findOne(n=>n.name==="TimeLabel").characters = d.time;
  i.findOne(n=>n.name==="CategoryLabel").characters = d.cat;
  if(d.fav){
    const fav = i.findOne(n=>n.name==="Icon_Favorite");
    recolor(fav, C.fav);
    i.findOne(n=>n.name==="Favorite").fills = solid(C.tint);
  }
  return i;
}
function grid(items, perRow, gap){
  const g = auto("VERTICAL", gap); g.name="Grid";
  let row = null;
  items.forEach((it, idx)=>{
    if(idx % perRow === 0){ row = auto("HORIZONTAL", gap); g.appendChild(row); }
    row.appendChild(it);
  });
  return g;
}
async function sectionHead(title, copy){
  const h = auto("HORIZONTAL", 24); h.name="SectionHead"; h.counterAxisAlignItems="CENTER";
  const left = auto("VERTICAL", 12); left.name="Titles";
  left.appendChild(await txt(title, 32, "Bold", C.text, {w:700, lh:40}));
  if(copy) left.appendChild(await txt(copy, 16, "Regular", C.sub, {w:640, lh:26}));
  h.appendChild(left);
  const g = figma.createFrame(); g.fills=[]; g.resize(10,1); g.layoutGrow=1;
  h.appendChild(g);
  return h;
}

