  box.primaryAxisSizingMode="FIXED"; box.counterAxisSizingMode="FIXED";
  if(checked){
    box.fills=solid(C.ink);
    const ck = await instance("7:33", 16, 16); ck.name="Icon_Check"; recolor(ck, C.white);
