const dump = (n, depth) => {
  let s = "  ".repeat(depth) + n.type + " " + n.name + (n.type==="INSTANCE"?" [main:"+(n.mainComponent?n.mainComponent.name:"?")+"]":"");
  let out = [s];
  if("children" in n) n.children.forEach(ch=>out=out.concat(dump(ch, depth+1)));
  return out;
};
