  photo.swapComponent(await figma.getNodeByIdAsync(d.photo));
  const av = i.findOne(n=>n.name==="Avatar" && n.type==="INSTANCE");
  av.swapComponent(await figma.getNodeByIdAsync(d.avatar));
  i.findOne(n=>n.name==="Title").characters = d.title;
  i.findOne(n=>n.name==="Excerpt").characters = d.excerpt;
  i.findOne(n=>n.name==="AuthorName").characters = d.author;
  i.findOne(n=>n.name==="Date").characters = d.date;
  return i;
}
function grid(items, perRow, gap){
  const g = auto("VERTICAL", gap); g.name="Grid";
  let row = null;
  items.forEach((it, idx)=>{
    if(idx % perRow === 0){ row = auto("HORIZONTAL", gap); g.appendChild(row); }
    row.appendChild(it);
  });
  return g;
}

